# run_bo_standard_deep_gp_5head.py # DeepGP + BO (5 heads) — stable training, no argparse, with quick train-fit check and LogEI BO import math import time from dataclasses import dataclass from typing import Tuple, Dict, List import torch import gpytorch import numpy as np from gpytorch.distributions import MultivariateNormal from gpytorch.variational import CholeskyVariationalDistribution try: # new-ish gpytorch from gpytorch.variational import WhitenedVariationalStrategy as _VS except Exception: # older gpytorch from gpytorch.variational import VariationalStrategy as _VS import matplotlib.pyplot as plt # Use double for a bit more numerical headroom with DeepGPs torch.set_default_dtype(torch.float64) # ========================= # Configuration (edit here) # ========================= @dataclass class TrainCfg: epochs_warmup: int = 180 # epochs before BO starts epochs_per_bo: int = 180 # epochs after each new BO point lr: float = 1e-2 # Adam LR (hypers + likelihoods) ngd_lr: float = 1e-1 # NGD LR (variational params) beta_start: float = 0.05 # ELBO beta anneal start beta_end: float = 0.30 # ELBO beta anneal end mc_min: int = 2 # min MC samples mc_max: int = 7 # max MC samples seed: int = 0 use_cuda: bool = torch.cuda.is_available() @dataclass class BOCfg: iters: int = 25 layers: int = 5 # for logging; the model below is per-head GPLayers acq: str = "log_ei" # "log_ei" only in this demo bounds: Tuple[float, float] = (-32.768, 32.768) grid_points: int = 512 maximize: bool = True # True because the demo objective returns negative Ackley # swap this out with your plant/simulator call def objective_neg_ackley(x: torch.Tensor) -> torch.Tensor: """ 1-D negative Ackley (so that best is near 0 and values are ~[-22, 0]). x: [N, 1] tensor returns: [N, 1] """ a, b, c = 20.0, 0.2, 2 * math.pi r2 = (x ** 2).mean(dim=1, keepdim=True) # d=1, so mean==sum term1 = -a * torch.exp(-b * torch.sqrt(r2)) term2 = -torch.exp(torch.cos(c * x).mean(dim=1, keepdim=True)) f = term1 + term2 + a + math.e return -f # negative Ackley -> peak ~0 at x=0, ~-22 at edges # You can replace this with your simulator hook: EVAL_OBJECTIVE = objective_neg_ackley train_cfg = TrainCfg() bo_cfg = BOCfg() device = torch.device("cuda" if (train_cfg.use_cuda and torch.cuda.is_available()) else "cpu") torch.manual_seed(train_cfg.seed) np.random.seed(train_cfg.seed) # ------------------------- # Model # ------------------------- class GPLayer(gpytorch.models.ApproximateGP): def __init__(self, input_dims: int, num_inducing: int): Z = torch.linspace(bo_cfg.bounds[0], bo_cfg.bounds[1], num_inducing).unsqueeze(-1) q = CholeskyVariationalDistribution(num_inducing) strategy = _VS(self, Z, q, learn_inducing_locations=True) super().__init__(strategy) self.mean_module = gpytorch.means.ZeroMean() self.covar_module = gpytorch.kernels.ScaleKernel( gpytorch.kernels.RBFKernel() ) def forward(self, x): mean_x = self.mean_module(x) covar_x = self.covar_module(x) return MultivariateNormal(mean_x, covar_x) class RWGSDeepGP(torch.nn.Module): """ Five independent GP 'heads' (compressor, pre, reactor, separator, output), all conditioned on the same 1-D input. """ def __init__(self, input_dims: int, num_layers: int, num_inducing: int): super().__init__() self.compressor = GPLayer(input_dims, num_inducing) self.pre = GPLayer(input_dims, num_inducing) self.reactor = GPLayer(input_dims, num_inducing) self.separator = GPLayer(input_dims, num_inducing) self.output = GPLayer(input_dims, num_inducing) def heads(self): return [self.compressor, self.pre, self.reactor, self.separator, self.output] def build_optimizers_for_head(head: GPLayer, likelihood: gpytorch.likelihoods.GaussianLikelihood, num_data: int) -> Tuple[torch.optim.Optimizer, torch.optim.Optimizer]: """ NGD for variational params only; Adam for hypers + likelihood. This avoids the duplicate-parameter warning. """ ngd = gpytorch.optim.NGD(head.variational_parameters(), num_data=num_data, lr=train_cfg.ngd_lr) adam = torch.optim.Adam([ {'params': head.hyperparameters()}, {'params': likelihood.parameters()}, ], lr=train_cfg.lr) return ngd, adam # ------------------------- # Training # ------------------------- def train_deepgp_stable( model: RWGSDeepGP, X: torch.Tensor, y_list: Tuple[torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor], header: str = "Train", ) -> Tuple[Dict[str, float], List[gpytorch.likelihoods.GaussianLikelihood]]: """ Trains the 5 independent heads with their own Gaussian likelihoods. Returns per-head RMSE/mean-LL metrics and the trained likelihoods (for inference/BO). """ model = model.to(device) heads = model.heads() likes = [gpytorch.likelihoods.GaussianLikelihood().to(device) for _ in range(5)] num_data = X.shape[0] X = X.to(device) ys = [t.to(device).squeeze(-1) for t in y_list] # Maintain explicit ELBO objects so we can set elbo.beta directly (no version hazards) elbos = [] mlls = [] opt_pairs: List[Tuple[torch.optim.Optimizer, torch.optim.Optimizer]] = [] for head, like in zip(heads, likes): elbo = gpytorch.mlls.VariationalELBO(like, head, num_data=num_data) mll = gpytorch.mlls.DeepApproximateMLL(elbo) ngd, adam = build_optimizers_for_head(head, like, num_data) elbos.append(elbo) mlls.append(mll) opt_pairs.append((ngd, adam)) total_epochs = train_cfg.epochs_warmup if header.lower().startswith("pre") else train_cfg.epochs_per_bo t0 = time.time() for epoch in range(1, total_epochs + 1): frac = epoch / total_epochs beta = train_cfg.beta_start + (train_cfg.beta_end - train_cfg.beta_start) * frac mc = int(round(train_cfg.mc_min + (train_cfg.mc_max - train_cfg.mc_min) * frac)) losses = [] for (head, like, elbo, mll), y, (ngd, adam) in zip(zip(heads, likes, elbos, mlls), ys, opt_pairs): head.train(); like.train() ngd.zero_grad(set_to_none=True); adam.zero_grad(set_to_none=True) elbo.beta = float(beta) with gpytorch.settings.num_likelihood_samples(mc): out = head(X) loss = -mll(out, y) loss.backward() ngd.step(); adam.step() losses.append(loss.item()) if epoch == 1 or epoch % 10 == 0: # quick hyper readout def ls_os(layer): ls = float(layer.covar_module.base_kernel.lengthscale.mean()) os = float(layer.covar_module.outputscale) return f"ls={ls:.3f}, os={os:.3f}" msg = " | ".join([ f"compressor({ls_os(model.compressor)})", f"pre({ls_os(model.pre)})", f"reactor({ls_os(model.reactor)})", f"separator({ls_os(model.separator)})", f"output({ls_os(model.output)})", ]) print(f"[Epoch {epoch:04d}] Loss={sum(losses):.3f} | β={beta:.3f} | MC={mc:02d} | {msg}") # ---- quick train-fit check (per head) ---- metrics: Dict[str, float] = {} for i, (head, like, y) in enumerate(zip(heads, likes, ys)): head.eval(); like.eval() with torch.no_grad(), gpytorch.settings.fast_pred_var(), gpytorch.settings.num_likelihood_samples(64): f = head(X) pred = like(f) mu = pred.mean rmse = torch.sqrt(torch.mean((mu - y) ** 2)).item() mean_ll = pred.log_prob(y).mean().item() metrics[f"head{i+1}_rmse"] = rmse metrics[f"head{i+1}_mean_ll"] = mean_ll elapsed = time.time() - t0 pretty = ", ".join([f"{k}={v:.3f}" for k, v in metrics.items()]) print(f"✅ {header} done in {elapsed:.2f}s | {pretty}") return metrics, likes # ------------------------- # Acquisition (LogEI) # ------------------------- def normal_pdf(z: torch.Tensor) -> torch.Tensor: return torch.exp(-0.5 * z ** 2) / math.sqrt(2.0 * math.pi) def normal_cdf(z: torch.Tensor) -> torch.Tensor: # stable CDF via erf return 0.5 * (1.0 + torch.erf(z / math.sqrt(2.0))) def expected_improvement(mu: torch.Tensor, sigma: torch.Tensor, best_y: float, maximize: bool) -> torch.Tensor: """ EI for Normal posterior; sigma is std, not variance. Returns shape [..., 1]. """ sigma = torch.clamp(sigma, min=1e-12) if maximize: z = (mu - best_y) / sigma ei = (mu - best_y) * normal_cdf(z) + sigma * normal_pdf(z) else: z = (best_y - mu) / sigma ei = (best_y - mu) * normal_cdf(z) + sigma * normal_pdf(z) return torch.clamp(ei, min=0.0) def acquisition_log_ei(mu: torch.Tensor, sigma: torch.Tensor, best_y: float, maximize: bool) -> torch.Tensor: ei = expected_improvement(mu, sigma, best_y, maximize) return torch.log(ei + 1e-12) # ------------------------- # Data helpers (demo) — replace with your plant I/O # ------------------------- def make_initial_training_data(n_init: int = 5) -> Tuple[torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor]: lb, ub = bo_cfg.bounds X = torch.linspace(lb, ub, n_init).unsqueeze(-1) y = EVAL_OBJECTIVE(X) # In this demo we put the same target on all 5 heads. Replace with your 5 outputs if you have them. return X, y.clone(), y.clone(), y.clone(), y.clone(), y.clone() def evaluate_at(x_new: torch.Tensor) -> Tuple[torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor]: y = EVAL_OBJECTIVE(x_new) return y.clone(), y.clone(), y.clone(), y.clone(), y.clone() def append_new_observation(X: torch.Tensor, y_tuple: Tuple[torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor], x_new: torch.Tensor, y_new_tuple: Tuple[torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor]): X = torch.cat([X, x_new], dim=0) y_tuple = tuple(torch.cat([y_old, y_new], dim=0) for y_old, y_new in zip(y_tuple, y_new_tuple)) return X, y_tuple # ------------------------- # Plotting # ------------------------- def plot_progress(iter_idx: int, X_obs: torch.Tensor, y_out_obs: torch.Tensor, grid_x: torch.Tensor, true_fx: torch.Tensor, post_mu: torch.Tensor, post_std: torch.Tensor, acq_vals: torch.Tensor, train_metrics: Dict[str, float]): fig = plt.figure(figsize=(7, 8)) gs = fig.add_gridspec(3, 1, height_ratios=[2, 2, 2]) ax1 = fig.add_subplot(gs[0, 0]) ax2 = fig.add_subplot(gs[1, 0]) ax3 = fig.add_subplot(gs[2, 0]) # Panel 1: objective ax1.set_title(f"DeepGP BO Progress (Iter {iter_idx})") ax1.plot(grid_x.cpu().numpy(), true_fx.cpu().numpy(), 'k--', label="True Ackley") ax1.scatter(X_obs.cpu().numpy(), y_out_obs.cpu().numpy(), c='r', s=30, label="Samples") ax1.set_ylabel("f(x)") ax1.legend(loc="upper right") ax1.grid(alpha=0.3) # Panel 2: posterior (output head) mu = post_mu.detach().cpu().numpy() std = post_std.detach().cpu().numpy() ax2.set_title(f"DeepGP Posterior | Train RMSE={train_metrics['head5_rmse']:.3f}, Mean LL={train_metrics['head5_mean_ll']:.2f}") ax2.fill_between(grid_x.squeeze(-1).cpu().numpy(), (mu - 2*std).squeeze(-1), (mu + 2*std).squeeze(-1), alpha=0.25) ax2.plot(grid_x.cpu().numpy(), mu, lw=2, label="Posterior mean") ax2.scatter(X_obs.cpu().numpy(), y_out_obs.cpu().numpy(), c='r', s=20, label="Samples") ax2.set_ylabel("Predicted mean") ax2.legend(loc="upper right") ax2.grid(alpha=0.3) # Panel 3: acquisition ax3.set_title("Acquisition Function") ax3.plot(grid_x.cpu().numpy(), acq_vals.detach().cpu().numpy(), label="LogEI") ax3.set_xlabel("x") ax3.set_ylabel("Acquisition") ax3.legend(loc="upper right") ax3.grid(alpha=0.3) fig.tight_layout() plt.show() # ------------------------- # Main # ------------------------- def main(): print(f"⚙️ Using FAST preset ({bo_cfg.layers} layers).") # Initial data X_s, y_c, y_p, y_r, y_spr, y_out = make_initial_training_data(n_init=5) y_tuple = (y_c, y_p, y_r, y_spr, y_out) # Build model base_num_inducing = min(64, max(16, X_s.shape[0])) model = RWGSDeepGP(input_dims=1, num_layers=bo_cfg.layers, num_inducing=base_num_inducing).to(device) # Warmup training print("\n📊 Plotting initial model state...") train_metrics, likes = train_deepgp_stable(model, X_s, y_tuple, header="Pretrain") # BO grid lb, ub = bo_cfg.bounds grid_x = torch.linspace(lb, ub, bo_cfg.grid_points).unsqueeze(-1).to(device) true_fx = EVAL_OBJECTIVE(grid_x).detach() # BO loop best_val = float(y_out.max().item()) if bo_cfg.maximize else float(y_out.min().item()) for it in range(1, bo_cfg.iters + 1): print(f"\n=== BO Iteration {it}/{bo_cfg.iters} ===") # Use OUTPUT head + its likelihood for acquisition out_head = model.output.eval() out_like = likes[4].eval() with torch.no_grad(), gpytorch.settings.fast_pred_var(), gpytorch.settings.num_likelihood_samples(64): f_post = out_head(grid_x) pred = out_like(f_post) mu = pred.mean std = pred.variance.sqrt() # Acquisition (LogEI) y_best = best_val acq = acquisition_log_ei(mu, std, y_best, maximize=bo_cfg.maximize) # Argmax acquisition on the grid idx = int(torch.argmax(acq).item()) x_next = grid_x[idx:idx+1].detach().cpu() # Observe plant/simulator (all five heads here share the same y for demo) yN_c, yN_p, yN_r, yN_spr, yN_out = evaluate_at(x_next) y_next_tuple = (yN_c, yN_p, yN_r, yN_spr, yN_out) # Update datasets X_s, y_tuple = append_new_observation(X_s, y_tuple, x_next, y_next_tuple) y_out = y_tuple[4] best_val = float(y_out.max().item()) if bo_cfg.maximize else float(y_out.min().item()) # Retrain after adding the new point train_metrics, likes = train_deepgp_stable(model, X_s, y_tuple, header=f"BO {it:02d}") # Plot progress with torch.no_grad(), gpytorch.settings.fast_pred_var(), gpytorch.settings.num_likelihood_samples(64): f_post = out_head(grid_x) pred = out_like(f_post) mu = pred.mean std = pred.variance.sqrt() print(f"→ Best value so far: {best_val:+.4f}") plot_progress(it, X_s, y_out, grid_x.cpu(), true_fx.cpu(), mu.cpu(), std.cpu(), acq.cpu(), train_metrics) if __name__ == "__main__": main()